  ASSERT_EQ(5, pv->num_buckets());

  std::vector<std::string> names{"Qui", "Quo", "Qua"};
  pv->RenameBuckets(names.cbegin(), names.cend());

  std::vector<string> buckets_names;
  auto buckets = pv->buckets();
  ASSERT_EQ(buckets.size(), pv->num_buckets());

