#include <map>
#include <memory>
#include <stdexcept>

// Forward declarations
class Bucket;
using BucketPtr = std::shared_ptr<Bucket>;

// Simple Bucket for testing
class Bucket {
public:
    Bucket(const std::string& name) : name_(name) {}
    std::string name() const { return name_; }
private:
    std::string name_;
};

// Comparator with tolerance (simplified)
template<int Tolerance = 5>
class FloatLessWithTolerance {
public:
    explicit FloatLessWithTolerance(double eps = pow(10, -Tolerance)) : epsilon_(eps) {}
    bool operator()(const float& left, const float& right) const {
        return (std::abs(left - right) > epsilon_) && (left < right);
    }
private:
    double epsilon_;
};

using MapWithTolerance = std::map<float, BucketPtr, FloatLessWithTolerance<>>;

BucketPtr view_find_bucket(const std::map<float, BucketPtr>& partition_to_bucket, float hash) {
    if (hash < 0.0f || hash > 1.0f) {
        throw std::invalid_argument("Hash must be in [0, 1] range");
    }
    if (partition_to_bucket.empty()) {
        return nullptr;
    }
    auto it = partition_to_bucket.upper_bound(hash);
    if (it == partition_to_bucket.end()) {
        it = partition_to_bucket.begin();
    }
    return it->second;
}

// Test
int main() {
    MapWithTolerance m;
    m[0.2] = std::make_shared<Bucket>("b1");
    m[0.5] = std::make_shared<Bucket>("b2");
    m[0.8] = std::make_shared<Bucket>("b3");

    auto b1 = view_find_bucket(m, 0.1);
    auto b2 = view_find_bucket(m, 0.2);
    auto b3 = view_find_bucket(m, 0.5);
    auto b4 = view_find_bucket(m, 0.8);
    auto b5 = view_find_bucket(m, 0.95); // wrap around

    return 0;
}

